Method.Implementation:

 	Try {
	 	// NEW $NAMESPACE
	 	// Set $NAMESPACE = "%SYS"
	 	WRITE !, $NAMESPACE
	 	Set tRS = ##class(%ResultSet).%New("%SYS.Namespace:List")
 		Set tSC = tRS.Execute()
        For {
            Quit:'tRS.Next()
            set nmSp = tRS.Get("Nsp")
            $$$LOGINFO(  nmSp _ ", " _ tRS.Get("Status"))
            if (tRS.Get("Status") = 1)
            {
	            Do ..GetComponents(nmSp)
        	}
       }
 	   Do tRS.Close()
 	} Catch eException {
		WRITE !, eException.AsStatus()
		RETURN "Exception in " _ $NAMESPACE
	}
	$$$LOGINFO( "Created setting files")
	RETURN "Created setting files"

	Try
	{
		set env = ""
		set sysEnv = $ZCVT($SYSTEM, "U")
		if ( $FIND(sysEnv, "PRD") > 0)
		{
			set env = "PROD"
		}
		elseif ( $FIND(sysEnv, "UAT") > 0)
		{
			set env = "UAT"
		}
		elseif ( $FIND(sysEnv, "QA") > 0)
		{
			set env = "QA"
		}
		else
		{
			set env = "DEV"
		}

    	// do ##class(IHC.EAI.GetSettings.Util).GetComponentsForNamespace(nmSp)
    	// $$$LOGINFO( "---- " _ nmSp _ " ---- " _ env _ " ----")

	 	New $NAMESPACE
		Set $NAMESPACE = nmSp
		// $$$LOGINFO( "GetComponents Namespace: " _ $NAMESPACE)

		// Report-level info
		Set tCreatedOn = $ZDATETIME($H,3)

		Set tProductionName = ##class(Ens.Director).GetActiveProductionName()

   		// $$$LOGINFO( "GetComponents " _ $NAMESPACE _ ", getProductionItems: " _ tProductionName)

   		Set tProduction = ##class(Ens.Config.Production).%OpenId(tProductionName,,.tStatus)


   		Set tStatus = ##class(Ens.Director).getProductionItems(tProduction,.tProductionDefinition)

   		If ($DATA(tProductionDefinition) = 10) {
	   		Set tConfigName = ""
			For { 
				Set tConfigName = $ORDER(tProductionDefinition(tConfigName))
				// WRITE !, tConfigName
				Quit:(tConfigName = "")
				Do ..CreateSettingFile(tConfigName, env, $NAMESPACE)
			}
    	}
    } Catch eException {
	    // $$$LOGINFO( "In eException: " _ nmSp)
		WRITE !, eException.AsStatus()
	}


set direc = "/itf-share/itf-tmp/itfSvnFiles/ITF_EnsembleReleasePkgs/batch/" _  env _ "/"
IF ' ##class(%File).DirectoryExists(direc)
{
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Creating: " _ direc)
     Do ##class(%File).CreateDirectoryChain(direc)
}
IF ' ##class(%File).DirectoryExists(direc)
{
	$$$LOGINFO( "No directory: " _ direc)
	RETURN $$$ERROR("No directory: " _ direc)
}

set tempFile = direc _ nmSp _ "-" _ tConfigName _ "-" _ env _".txt" 

Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Creating: " _ tempFile)
Set file=##class(%File).%New(tempFile)

Do file.Open("WN")
Do file.WriteLine("# Settings file for: "  _ tConfigName _ ", Namepsace: " _ nmSp _ ", Environment: " _ env)
try {


		#dim tItem As Ens.Config.Item
		Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(tConfigName)
		If ' $IsObject(tItem)
		{
			Do file.WriteLine("# Can't open object: " _ tConfigName) 	
		}
		else
		{
	   			// $$$LOGINFO("Creating Settings file for: "  _ tConfigName)
				// Analyze static settings for this component/config item

				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( tItem.Name _ ", ID: " _ tItem.%Id())
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( tItem.Production.Name)
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "tConfigItem properties: " _ tItem.ClassName _ ", " _ tItem.Comment)
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "tConfigItem settings: " _ tItem.Settings)

				/******** Process static settings ****/
				// 
				Do file.WriteLine(  "# Static Settings")
				Set tStatus = tItem.GetStaticSettings(.tStaticSettings)
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "GetStaticSettings: " _ tStatus _", " _ $DATA(tStaticSettings))
				If ($DATA(tStaticSettings) = 10) {

					set ind = 1
					Set tSettingName = ""
					Set tSettingIndex = ""
					For {
						Set tSettingIndex = $ORDER(tStaticSettings(tSettingIndex))
						Quit:(tSettingIndex = "")

						Set tSettingList = tStaticSettings(tSettingIndex)
						Set tSettingName = $LG(tSettingList,2)

						// Grab the value
						Set tCurrentValue = $LG(tSettingList,3)


						Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "  StaticSettings #$# " _
													tSettingName _ ", val: " _ tCurrentValue )
						Do file.WriteLine(  "Static #$# " _ tSettingName _"#$# "_tCurrentValue)
					} // end For

				} // End if $DATA(tStaticSettings) = 10 
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "  StaticSettings END")

				Set tStatus = ##class(Ens.Director).GetHostSettings(tConfigName,.tHostSettings)
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(  "  GetHostSettings: " _ tStatus _ ", " _ $DATA(tHostSettings))

				Do file.WriteLine(  "# Host Settings")
				If ($DATA(tHostSettings) = 10) {	

					Set tSettingName = ""

					For {
						Set tSettingName = $ORDER(tHostSettings(tSettingName))
						Quit:(tSettingName = "")

						Set tCurrentValue = tHostSettings(tSettingName)


						Do file.WriteLine(  "Host #$# " _ tSettingName _"#$# "_tCurrentValue)

					}  
				} // End if $DATA(tHostSettings) = 10

				/***** Process adapter settings *****/
				Set tStatus = ##class(Ens.Director).GetAdapterSettings(tConfigName,.tAdapterSettings)
				Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "GetAdapterSettings: " _ tStatus _ ", " _ $DATA(tAdapterSettings))
				Do file.WriteLine(  "# Adapter Settings")
				If ($DATA(tAdapterSettings) = 10) {	

					Set tSettingName = ""

					For {
						Set tSettingName = $ORDER(tAdapterSettings(tSettingName))
						Quit:(tSettingName = "")

						Set tCurrentValue = tAdapterSettings(tSettingName)


						Do file.WriteLine(  "Adapter #$# " _ tSettingName _"#$# "_tCurrentValue)

					}  
				} // End if $DATA(tAdapterSettings) = 10
		}
		set retStr = "; New file created: " _ tempFile

} catch(err)
{
	Do file.WriteLine("#Could not create setting files " _ err)
}
Do file.Close()
return $$$OK
